// FoundationStereo's context path (`ContextNetDino` and the `cam` / `sam` attention
// its forward applies), against PyTorch in FP64.
//
// The committed fixtures cover the pieces with seeded random weights (BatchNorm
// running statistics randomised); the whole network, whose fixed 64/96/128 widths
// make random-weight fixtures large, is checked against the real checkpoint only.
// Fixtures generated by tests/fixtures/context/generate.py and gen_real.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use teeny_core::name_scope::name_scope;
use vision_rs::models::stereo::feature::context::{
    ContextDims, channel_attention, context, residual_block, spatial_attention,
};

/// `ResidualBlock(64, 96, norm_fn='batch', stride=2)` in eval mode on 12x18, with the
/// strided 1x1 shortcut.
#[test]
#[serial]
fn residual_block_batch_norm_matches_pytorch() -> anyhow::Result<()> {
    check_block(
        "context/resblock",
        "context/resblock",
        &[("x", &[1, 64, 12, 18])],
        |i| {
            let _g = name_scope("blk");
            vec![("", residual_block::<f32>(&i[0], 64, 96, 2))]
        },
        1e-4,
    )?;
    Ok(())
}

/// `inp = cam(x) * x` and `att = sam(inp)` on 32 channels at 9x13.
#[test]
#[serial]
fn channel_and_spatial_attention_match_pytorch() -> anyhow::Result<()> {
    check_block(
        "context/attention",
        "context/attention",
        &[("x", &[1, 32, 9, 13])],
        |i| {
            let inp = {
                let _g = name_scope("cam");
                channel_attention::<f32>(&i[0], 32)
            };
            let att = {
                let _g = name_scope("sam");
                spatial_attention::<f32>(&inp)
            };
            vec![("inp", inp), ("att", att)]
        },
        1e-5,
    )?;
    Ok(())
}

/// The whole context path with a real FoundationStereo checkpoint's `cnet`, `cam` and
/// `sam` weights, on the sample left image at 224x320 with its real `vit_feat`
/// (56x80), against PyTorch in FP64: `net`, `inp` and `att` at 1/4, 1/8 and 1/16.
/// Build the fixtures with tests/fixtures/context/gen_real.py, point
/// `FS_REAL_FIXTURES` at the directory holding `context_real/` and run with
/// `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn context_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/context_real");
    check_block(
        "context_real",
        &dir,
        &[("image", &[1, 3, 224, 320]), ("vit", &[1, 128, 56, 80])],
        |i| {
            let c = context::<f32>(&ContextDims::foundation_stereo(), &i[0], &i[1]);
            let [n0, n1, n2] = c.net;
            let [i0, i1, i2] = c.inp;
            let [a0, a1, a2] = c.att;
            vec![
                ("net0", n0),
                ("net1", n1),
                ("net2", n2),
                ("inp0", i0),
                ("inp1", i1),
                ("inp2", i2),
                ("att0", a0),
                ("att1", a1),
                ("att2", a2),
            ]
        },
        1e-4,
    )?;
    Ok(())
}
